const turns = $input.item.json.turns || [];
const text = turns.map(t => (t.role === 'assistant' ? 'Agent: ' : 'Customer: ') + (t.text||'')).join('\n');
return [{ json: { call_id: $('Webhook Status').item.json.query.call_id, text } }];

// Pull tool outputs
const sum = (($('Claude Summarise').item.json.content||[]).find(b=>b.type==='tool_use')||{}).input||{};
const f = (($('Claude Extract').item.json.content||[]).find(b=>b.type==='tool_use')||{}).input||{};
// Score (port of lead_scoring.py)
const TL = {'immediate':35,'1-3 months':25,'3-6 months':12,'researching':4};
let s=0; const t=(f.purchase_timeline||'').toLowerCase();
for (const k in TL) if (t.includes(k)){ s+=TL[k]; break; }
if (f.budget) s+=20; if (f.vehicle_interest) s+=15; if (f.email) s+=8;
if (f.financing_need) s+=7; if (f.trade_in_interest) s+=5;
if (sum.sentiment==='positive') s+=10; else if (sum.sentiment==='negative') s-=10;
s=Math.max(0,Math.min(100,s));
const temperature = s>=65?'hot':s>=35?'warm':'cold';
const conversion_probability = Math.min(0.95, Math.max(0.02, s/110));
const statusMap = { appointment_booked:'appointment_set', do_not_call:'do_not_call', qualified:'qualified', needs_followup:'qualified', callback_requested:'qualified', not_interested:'lost' };
const status = statusMap[sum.outcome] || 'contacted';
return [{ json: { call_id: $('Render Transcript').item.json.call_id, fields: f, summary: sum, score: s, temperature, conversion_probability, status } }];
